def get_neighbors(grid, r, c, padded=False):
    """Get all 8 neighbors of (r, c), excluding (r,c) itself"""
    rows, cols = grid.shape
    if padded:
        padded_grid = np.pad(grid, 1, mode='constant')  # Add a border of 0s
        neighs = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                neighs.append(padded_grid[r+dr, c+dc])
        return neighs
    else:
        neighs = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    neighs.append(grid[nr, nc])
        return neighs

