def copy_from_nearest_priority(grid, target_val=6, priority=['right', 'down', 'left']):
    """For each target cell, copy from nearest non-target in priority order"""
    result = grid.copy()
    rows, cols = grid.shape

    for r in range(rows):
        for c in range(cols):
            if grid[r, c] == target_val:
                found = None
                for direction in priority:
                    if found:
                        break
                    if direction == 'right':
                        for kc in range(c + 1, cols):
                            if result[r, kc] != target_val:
                                result[r, c] = result[r, kc]
                                found = result[r, kc]
                        break
                    elif direction == 'down':
                        for kr in range(r + 1, rows):
                            if result[kr, c] != target_val:
                                result[r, c] = result[kr, c]
                                found = result[kr, c]
                        break
                    elif direction == 'left':
                        for kc in range(c - 1, -1, -1):
                            if result[r, kc] != target_val:
                                result[r, c] = result[r, kc]
                                found = result[r, kc]
                        break
                    elif direction == 'up':
                        for kr in range(r - 1, -1, -1):
                            if result[kr, c] != target_val:
                                result[r, c] = result[kr, c]
                                found = result[kr, c]
                        break

    return result

