                right_val = result[r, min(n-1, end)] if end < n else 0

                # For each 6 in segment, fill from nearest non-6
                for k in range(start, end):
                    to_left = k - start  # distance to start of segment
                    to_right = end - k  # distance to end of segment

                    # Fill from the closer boundary
                    if to_left <= to_right:
                        result[r, k] = left_val
                    else:
                        result[r, k] = right_val

                # If only one side exists, use that
                if left_val == 0 and right_val != 0:
                    for k in range(start, end):
                        result[r, k] = right_val
                elif right_val == 0 and left_val != 0:
                    for k in range(start, end):
                        result[r, k] = left_val
            else:
                c += 1

    return result

