def fill_with_priority(grid, priority=['right', 'down', 'left', 'up']):
    """Fill 6s with nearest non-6 in priority order"""
    result = grid.copy()
    rows, cols = grid.shape

    def find_nearest(r, c, directions):
        for direction in directions:
            if direction == 'right':
                for kc in range(c + 1, cols):
                    if result[r, kc] != 6:
                        return result[r, kc], 'right'
            elif direction == 'down':
                for kr in range(r + 1, rows):
                    if result[kr, c] != 6:
                        return result[kr, c], 'down'
            elif direction == 'left':
                for kc in range(c - 1, -1, -1):
                    if result[r, kc] != 6:
                        return result[r, kc], 'left'
            elif direction == 'up':
                for kr in range(r - 1, -1, -1):
                    if result[kr, c] != 6:
                        return result[kr, c], 'up'
        return None, None

    for r in range(rows):
        for c in range(cols):
            if grid[r, c] == 6:
                val, dir = find_nearest(r, c, priority)
                if val:
                    result[r, c] = val

    return result

# Test with different priority orders
