# Let me try STRICT right-first for horizontal, down-for-no-horizontal
def smart_fill(grid):
    """If 6s are in a horizontal segment, fill from left/right. If vertical, fill from up/down."""
    result = grid.copy()
    rows, cols = grid.shape

    for r in range(rows):
        c = 0
        while c < cols:
            if grid[r, c] == 6:
                start, end = c, c
                while c + 1 < cols and grid[r, c+1] == 6:
                    c += 1
                    end += 1
                end -= 1

                # This is a horizontal segment
                left_val = result[r, start-1] if start > 0 else 0
                right_val = result[r, end+1] if end < cols - 1 else 0

                # Fill from left if left exists and is closer, else right
                for k in range(start, end+1):
                    if left_val != 0:
                        result[r, k] = left_val
                    elif right_val != 0:
                        result[r, k] = right_val
                    else:
                        # No horizontal fill, try vertical
                        for kr in range(r+1, rows):
                            if result[kr, c] != 6:
                                result[r, k] = result[kr, c]
                                break
                c = end + 1
            else:
                c += 1

    return result

